from math import ceil


class BaseAnalysis(object):
    @staticmethod
    def calculate_rounded_average(values, precision=None):
        if not values:
            raise ValueError('No values to average over')
        avg = float(sum(values)) / float(len(values)) if values else 0.0
        avg = round(avg, precision) if precision else round(avg)

        return avg

    def calculate_rounded_up_average(self, values):
        avg = self.calculate_rounded_average(values, precision=4)
        return int(ceil(avg))

    @staticmethod
    def _get_time_diff_in_ttis(timestamp_a, timestamp_b):
        # type: (str, str) -> int
        """
        based on Public Function getTimeDiffInTtis in TtiAnalyzer macros

        TTI - Transmission Time Interval is 1ms, hence the below algorithm
        """
        if not timestamp_a:
            timestamp_a = timestamp_b

        ts_a = list(map(int, timestamp_a.split(':')))
        ts_b = list(map(int, timestamp_b.split(':')))

        ts_a_in_ttis = (ts_a[0] * 60 * 60 * 1000) + (ts_a[1] * 60 * 1000) + (ts_a[2] * 1000) + ts_a[3]
        ts_b_in_ttis = (ts_b[0] * 60 * 60 * 1000) + (ts_b[1] * 60 * 1000) + (ts_b[2] * 1000) + ts_b[3]

        return abs(ts_a_in_ttis - ts_b_in_ttis)
